try{
    $annualSetupMeta=\Kulturhus\Verein\BalanceSetupForm::metadata($annualSetupOld);$annualSetupLedger=new \Kulturhus\Verein\BalanceLedger($db,(string)$_SESSION['actor']);$annualSetupCurrent=$annualSetupLedger->report($annualSetupMeta['year']);
