    if($annualSetupRetry&&$annualSetupMeta['action']==='balance-opening-reconcile'){$annualSetupPrior=$annualSetupLedger->report($annualSetupMeta['year']-1);$annualSetupRetry=$annualSetupPrior['state']==='closed'&&$annualSetupPrior['issues']===[]&&$annualSetupPrior['closed_sha256']===$annualSetupOld['prior_hash']&&$annualSetupCurrent['previous_sha256']!==$annualSetupOld['prior_hash'];}
