$annualSetupAccounts=$annualSetupCurrent['accounts']??[];$annualSetupAction=input($annualSetupOld,'action');$annualSetupTitle=match($annualSetupAction){'balance-create'=>'Bilanzjahr anlegen','balance-account'=>'Konto einrichten','balance-opening-reconcile'=>'Berichtigtes Vorjahr übernehmen',default=>'Anfangsbestände prüfen'};
?>
