<?php if($annualSetupCurrent!==null): ?><section class="card" data-annual-setup-current><h2><?= e($annualSetupText('Aktueller Jahresstand')) ?></h2><p><?= e((string)$annualSetupCurrent['year']) ?></p><p><?= e($annualSetupText(match($annualSetupCurrent['state']){'missing'=>'Bilanzjournal und geprüfte Anfangsbestände fehlen.','setup'=>'Anfangsbestände prüfen','open'=>'Buchungsstand offen',default=>'Buchungsstand festgeschrieben'})) ?></p><p><?= e($annualSetupText('Dieser Link zeigt den aktuellen Jahresstand. Er bestätigt weder diesen Auftrag noch eine damalige Anfangsbestandsfassung.')) ?></p><a class="btn btn-outline" data-annual-setup-current-link href="<?= e(url(['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$annualSetupCurrent['year']])) ?>"><?= e($annualSetupText('Aktuellen Jahresstand öffnen')) ?></a></section><?php endif ?>
<?php if($annualSetupRetry): ?><form method="post" action="<?= e(url(\Kulturhus\Verein\BalanceSetupForm::route($annualSetupOld))) ?>" class="card" data-annual-setup-operation="<?= e($annualSetupAction) ?>" data-unsaved-changes>
<?= csrf().hidden('action',$annualSetupOld['action']).hidden('balance_year',$annualSetupOld['balance_year']).hidden('version',$annualSetupOld['version']) ?>
<?php if($annualSetupAction==='balance-account'): ?>
