<label><?= e($annualSetupText('Eigene Bezeichnung · optional bei SKR42')) ?><input class="form-control" name="account_name" maxlength="160" value="<?= e($annualSetupOld['account_name']) ?>"></label>
<label><?= e($annualSetupText('Bilanzbereich · falls nicht automatisch zugeordnet')) ?><select class="form-control" name="account_group"><option value=""><?= e($annualSetupText('Bitte auswählen')) ?></option><?php if($annualSetupOld['account_group']!==''&&!isset(\Kulturhus\Verein\BalanceCalculation::GROUPS[$annualSetupOld['account_group']])): ?><option value="<?= e($annualSetupOld['account_group']) ?>" selected><?= e($annualSetupText('Bisherige Auswahl anhand der Belege prüfen.')) ?></option><?php endif ?><?php foreach(\Kulturhus\Verein\BalanceCalculation::GROUPS as$key=>[$label]): ?><option value="<?= e($key) ?>" <?= $annualSetupOld['account_group']===$key?'selected':'' ?>><?= e($annualSetupText($label)) ?></option><?php endforeach ?></select></label>
