<?php else:foreach(['debit'=>'Soll · EUR','credit'=>'Haben · EUR']as$key=>$label): ?><label><?= e($account['name'].' · '.$annualSetupText($label)) ?><input class="form-control" name="opening[<?= e($id) ?>][<?= e($key) ?>]" inputmode="decimal" value="<?= e(input($annualSetupOld['opening'][$id]??[],$key)) ?>" required></label><?php endforeach;endif;endforeach ?>
