<?php if($annualSetupAction==='balance-opening-reconcile'):$annualSetupProposed=\Kulturhus\Verein\BalanceCalculation::carryForward($annualSetupPrior['calculation'],$annualSetupCurrent['result_account']);$annualSetupStart=\Kulturhus\Verein\BalanceCalculation::build($annualSetupMeta['year'],$annualSetupAccounts,$annualSetupProposed,[]);foreach($annualSetupStart['accounts']as$id=>$account):$annualSetupWas=$annualSetupCurrent['calculation']['accounts'][$id]['opening_cents'];if($annualSetupWas===$account['opening_cents'])continue;$annualSetupSign=in_array($account['group'],['equity','reserves','provisions','liabilities','member_payables','deferred'],true)?-1:1; ?><p data-annual-setup-opening-change><?= e($account['name']) ?>: <?= e(number_format($annualSetupSign*$annualSetupWas/100,2,',','.').' €') ?> → <?= e(number_format($annualSetupSign*$account['opening_cents']/100,2,',','.').' €') ?></p><?php endforeach;endif ?>
<?php if(in_array($annualSetupAction,['balance-opening','balance-opening-reconcile'],true)): ?>
<?php if($annualSetupAction==='balance-opening-reconcile'): ?><?= hidden('prior_hash',$annualSetupOld['prior_hash']) ?><?php endif ?>
<label><?= e($annualSetupText($annualSetupAction==='balance-opening'?'Nachweis der Anfangsbestände':'Prüfvermerk')) ?><input class="form-control" name="evidence" maxlength="500" value="<?= e($annualSetupOld['evidence']) ?>" required></label><label class="check"><input class="check" type="checkbox" name="reviewed" value="1" <?= input($annualSetupOld,'reviewed')==='1'?'checked':'' ?> required><?= e($annualSetupText($annualSetupAction==='balance-opening'?'Alle Anfangsbestände geprüft, einschließlich der Nullbeträge.':'Die geänderten Anfangsbestände und die laufenden Buchungen wurden geprüft.')) ?></label>
