<?= hidden(\Kulturhus\Verein\BalanceSetupForm::COMPLETE,input($annualSetupOld,\Kulturhus\Verein\BalanceSetupForm::COMPLETE)) ?><button class="btn btn-solid theme-primary"><?= e($annualSetupText(match($annualSetupAction){'balance-create'=>'Bilanzjahr anlegen','balance-account'=>'Konto hinzufügen','balance-opening'=>'Anfangsbestände übernehmen',default=>'Anfangsbestände abgleichen'})) ?></button></form>
<?php else: ?><p><?= e($annualSetupText('Die ursprünglichen Angaben bleiben lesbar. Für neue Buchungen den aktuellen Stand und die aktuellen Rechte prüfen.')) ?></p><?php endif ?>
